lessons.solution:
import weakref
def weak_cache(factory):
    cache = weakref.WeakValueDictionary()
    def get(key):
        value = cache.get(key)
        if value is None:
            value = factory(key)
            cache[key] = value
        return value
    return get

def take_owned(iterator,n):
    try:
        if n<0: raise ValueError('negative count')
        result=[]
        for _ in range(n):
            try: result.append(next(iterator))
            except StopIteration: break
        return result
    finally:
        close=getattr(iterator,'close',None)
        if close is not None: close()

