        return None

lessons.solution:
class NonNegative:
    def __set_name__(self,owner,name):self.storage='_'+name
    def __get__(self,instance,owner=None):
        if instance is None:return self
        return instance.__dict__.get(self.storage,0)
    def __set__(self,instance,value):
        if type(value) is not int or value<0:raise ValueError('nonnegative integer required')
        instance.__dict__[self.storage]=value

